function rowChecklist(rows,field,d){return rows.length?'<div class="checklist">'+rows.map(r=>'<label class="check"><input type="checkbox" data-array-draft="scenario" data-array-field="'+field+'" value="'+E(r.row_id)+'"'+(d[field].includes(r.row_id)?" checked":"")+'><span>'+E(r.values.scope||r.values.programme||r.values.scenario_label||r.values[A.status.tables[r.table].key])+'<small> · '+E(r.values.metric||r.values.status||r.values.planned_year||"Timing not supplied")+' · '+E(valueText(r.values.amount??r.values.capital_cost))+' '+E(r.values.currency||"")+'</small></span></label>').join("")+'</div>':'<p class="help">No matching rows loaded. This source does not establish an available forecast.</p>';}
